import{_ as a,o as i,c as t,a2 as d}from"./chunks/framework.D7WGirly.js";const k=JSON.parse('{"title":"ビルドと公開パイプライン","description":"Palleriaのビルド環境、Gradleの手順、署名付きリリース、GitHub Actionsと-F-Droid連携、ベースラインプロファイルを解説します。","frontmatter":{"title":"ビルドと公開パイプライン","description":"Palleriaのビルド環境、Gradleの手順、署名付きリリース、GitHub Actionsと-F-Droid連携、ベースラインプロファイルを解説します。"},"headers":[],"relativePath":"dev/build.md","filePath":"dev/build.md","lastUpdated":1795329637000}'),s={name:"dev/build.md"};function l(o,e,r,n,p,c){return i(),t("div",null,[...e[0]||(e[0]=[d(`<h1 id="ビルドと公開パイプライン" tabindex="-1">ビルドと公開パイプライン <a class="header-anchor" href="#ビルドと公開パイプライン" aria-label="Permalink to &quot;ビルドと公開パイプライン&quot;">​</a></h1><p>このページは2026年11月16日に <code>app/build.gradle</code>、Gradle Wrapper、GitHub Actionsを確認した内容です。設定を変更した場合はコード側の値を優先してください。</p><h2 id="開発環境" tabindex="-1">開発環境 <a class="header-anchor" href="#開発環境" aria-label="Permalink to &quot;開発環境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>リポジトリの設定</th></tr></thead><tbody><tr><td>Gradle</td><td>Wrapperで9.8.2を取得（<code>distributionSha256Sum</code> で改ざん検証）</td></tr><tr><td>Gradle daemon JVM</td><td>ツールチェーン21（<code>gradle/gradle-daemon-jvm.properties</code> の <code>toolchainVersion=21</code>）</td></tr><tr><td>Javaソース・バイトコード</td><td>17</td></tr><tr><td>Android SDK</td><td>compileSdk 37、targetSdk 37、minSdk 24</td></tr><tr><td>ドキュメント</td><td>Node.jsとnpm。docsのCIはNode.js 22を使用</td></tr></tbody></table><p>JDK 17というコンパイル設定と、Gradle daemonのJDK 21指定は別です。daemon JVMは <code>gradle/gradle-daemon-jvm.properties</code> で固定しており、PATH上の <code>java</code> には依存しません。</p><h2 id="準備とビルド" tabindex="-1">準備とビルド <a class="header-anchor" href="#準備とビルド" aria-label="Permalink to &quot;準備とビルド&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/yunfie-twitter/Palleria.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Palleria</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :app:assembleDebug</span></span></code></pre></div><p>Windows PowerShellでは最後のコマンドを <code>.\\gradlew.bat :app:assembleDebug</code> に置き換えます。Android SDKの場所はAndroid Studioまたは <code>local.properties</code> で設定します。</p><p>Pixiv API クライアントは Kotlin（OkHttp + kotlinx.serialization）で実装しているため、ネイティブライブラリのビルドは不要です。</p><h3 id="debugビルドを速くする" tabindex="-1">debugビルドを速くする <a class="header-anchor" href="#debugビルドを速くする" aria-label="Permalink to &quot;debugビルドを速くする&quot;">​</a></h3><table tabindex="0"><thead><tr><th>設定</th><th>既定</th><th>上書き</th></tr></thead><tbody><tr><td>ABI別APK分割</td><td>有効</td><td><code>-Ppalleria.splits=false</code> で無効</td></tr></tbody></table><p>AGP 9.5の <code>splits.abi</code> はvariant単位で切り替えられないモジュール全体の設定です。そのため分割APKの無効化はローカル専用の <code>-Ppalleria.splits=false</code> で行い、CIとリリースは既定（有効）のままにしています。無効にしてもuniversal APKは生成されます。</p><h2 id="署名付きリリース" tabindex="-1">署名付きリリース <a class="header-anchor" href="#署名付きリリース" aria-label="Permalink to &quot;署名付きリリース&quot;">​</a></h2><p><code>KEYSTORE_PATH</code>、<code>KEYSTORE_PASSWORD</code>、<code>KEY_ALIAS</code>、<code>KEY_PASSWORD</code> を設定して <code>./gradlew :app:assembleRelease</code> を実行します。相対キーストアパスはappモジュール基準です。未設定時はコード上debug署名へフォールバックするので、配布用には必ずrelease署名を用意してください。</p><p>出力は <code>app/build/outputs/apk/release/</code> 以下です。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Palleria-v&lt;versionName&gt;-release-universal.apk</span></span>
<span class="line"><span>Palleria-v&lt;versionName&gt;-release-arm64-v8a.apk</span></span>
<span class="line"><span>Palleria-v&lt;versionName&gt;-release-armeabi-v7a.apk</span></span>
<span class="line"><span>Palleria-v&lt;versionName&gt;-release-x86_64.apk</span></span></code></pre></div><h2 id="github-releaseとf-droid" tabindex="-1">GitHub ReleaseとF-Droid <a class="header-anchor" href="#github-releaseとf-droid" aria-label="Permalink to &quot;GitHub ReleaseとF-Droid&quot;">​</a></h2><ul><li><code>release-apk.yml</code>: mainの <code>app/build.gradle</code> 更新、<code>v*</code> タグpush、手動実行でビルドします。成功時はDraft Releaseを作成し、ビルド失敗時もタグを保持します。</li><li><code>fdroid.yml</code>: Releaseの公開・削除イベントで起動します。公開時は添付APKを取得・検証し、削除時は対応するAPKを取り除いてインデックスを更新します。</li><li><code>docs.yml</code>: ドキュメントをビルドして同じ <code>gh-pages</code> へ公開します。F-Droid更新と共通のキューで直列化し、互いの成果物を保持します。</li><li><code>kotlin-quality.yml</code>: ktlint・detekt・Android Lint を1ジョブで実行します。Gradleキャッシュはmainで更新し、PRからは読み取り専用で利用します。</li></ul><p><code>release-apk.yml</code> と <code>nightly.yml</code> は Gradle のバージョンをCI側で固定せず、Wrapperの定義に従います。</p><p>公開・復旧の詳しい手順は<a href="https://github.com/yunfie-twitter/Palleria/blob/main/.github/RELEASING.md" target="_blank" rel="noreferrer">RELEASING.md</a>を参照してください。</p><h2 id="ドキュメントの確認" tabindex="-1">ドキュメントの確認 <a class="header-anchor" href="#ドキュメントの確認" aria-label="Permalink to &quot;ドキュメントの確認&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span></span></code></pre></div><p>生成先は <code>docs/.vitepress/dist</code>、配信は <code>https://palleria.yunfie.date/</code> をルート（base <code>/</code>）にしています。ページ画像は <code>docs/assets</code> に置き、Markdownから相対パスで参照するとビルド時にURLが解決されます。</p><h2 id="起動プロファイルと計測" tabindex="-1">起動プロファイルと計測 <a class="header-anchor" href="#起動プロファイルと計測" aria-label="Permalink to &quot;起動プロファイルと計測&quot;">​</a></h2><p><code>app/src/main/baselineProfiles/</code> には <code>baseline-prof.txt</code> と <code>startup-prof.txt</code> を配置しています。現在のファイルはクラス単位の暫定ルールです。<code>benchmark</code> モジュールの <code>BaselineProfileGenerator</code> は <code>includeInStartupProfile = true</code> を指定し、起動経路から両方のプロファイルを生成します。</p><p>AGP 9.5.0 では DEX レイアウト最適化が既定で有効です。release は <code>minifyEnabled = true</code> で R8 を使用します。<code>app/build.gradle</code> に <code>startupProfile</code> や <code>dexLayoutOptimization</code> の明示指定がないことだけでは、無効とは判断できません。<a href="https://developer.android.com/topic/performance/startupprofiles/dex-layout-optimizations" target="_blank" rel="noreferrer">Android の公式説明</a>も参照してください。</p><p>Android SDK・NDK と設定済みの管理対象デバイスを利用できる環境で <code>./gradlew :app:generateBaselineProfile</code> を実行し、生成したルールを確認・更新します。<code>StartupBenchmark</code> はプロファイル適用有無のコールド起動と、適用時のウォーム起動を各10回測定します。ただし同一APKでの ART コンパイル条件の比較だけでは、ビルド時の DEX 配置最適化の効果を単独では測定できません。DEX 最適化の適用は release ビルドの R8 出力でも確認し、短縮時間は実機の測定結果から判断してください。</p><p>ABI 別 APK と universal APK は配布形式の違いです。複数 ABI の同梱だけで、すべての共有ライブラリを起動時にロードするわけではありません。</p><p>Sentry は <code>io.sentry.auto-init = false</code> に加え、SDK が追加する <code>SentryInitProvider</code>・<code>SentryPerformanceProvider</code>・<code>SentryNdkPreloadProvider</code> を Manifest マージで除外しています。これにより、手動初期化前のライフサイクル登録や起動プロファイル設定ファイルの確認を避けます。代わりに Sentry による初期化前の自動起動計測は行いません。ユーザー操作・ネットワークイベントのブレッドクラムも無効です。テレメトリに同意している場合、起動後の処理で SDK を初期化します。トレース率は Manifest と <code>GlitchTipTelemetry</code> の両方で <code>1.0</code>（100%）に設定されています。これは同意済みのトレースを全件サンプリングする指定であり、起動前から自動計測する指定ではありません。</p>`,29)])])}const u=a(s,[["render",l]]);export{k as __pageData,u as default};
